<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';
$user=require_login();$s=db()->prepare('SELECT f.*,c.job_id,c.status conversion_status FROM files f LEFT JOIN conversions c ON c.output_file_id=f.id WHERE f.user_id=? AND f.status<>"deleted" ORDER BY f.created_at DESC LIMIT 200');$s->execute([$user['id']]);$files=$s->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>File Manager - <?=e(APP_NAME)?></title><style>body{font-family:Arial;background:#0b1020;color:#e5e7eb;margin:0}.wrap{max-width:1100px;margin:auto;padding:28px}.nav{display:flex;gap:10px;margin-bottom:20px}.nav a{color:#fff;text-decoration:none;background:#1e293b;padding:10px 14px;border-radius:8px}.card{background:#151d33;padding:20px;border-radius:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #29334c}small{color:#94a3b8}.download{color:#fff;text-decoration:none;background:#2563eb;padding:7px 10px;border-radius:7px}@media(max-width:700px){table{font-size:12px}.hide-sm{display:none}}</style></head><body><div class="wrap"><div class="nav"><a href="dashboard.php">Dashboard</a><a href="converter.php">Converter</a><a href="files.php">File Manager</a></div><h1>📁 File Manager</h1><div class="card"><table><thead><tr><th>Nama</th><th>Jenis</th><th>Ukuran</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($files as $f):?><tr><td><?=e($f['original_name'])?><br><small><?=e($f['mime_type'])?></small></td><td><?=e($f['type'])?></td><td><?=number_format((int)$f['size_bytes']/1048576,2)?> MB</td><td><?=e($f['conversion_status']?:$f['status'])?></td><td><?php if($f['type']==='midi'&&$f['status']==='active'):?><a class="download" href="api/files/download.php?id=<?=((int)$f['id'])?>">Download MIDI</a><?php endif;?></td></tr><?php endforeach;if(!$files):?><tr><td colspan="5">Belum ada file.</td></tr><?php endif;?></tbody></table></div></div></body></html>